export function compartmentsForBeat(beatId: string): CompartmentUnit[] {
  const ids = compartmentsByBeat[beatId] ?? [];
  const byId = new Map(mockCompartments.map((c) => [c.id, c]));
  return ids.map((id) => byId.get(id)).filter(Boolean) as CompartmentUnit[];
}
